#!/usr/bin/env node
// Builds the site's one inline SVG sprite from lucide-static into
// packages/ui/src/icon-sprite.generated.ts. Only the icons listed here go in; add a name, run
// `node scripts/icon-sprite.mjs`, and commit the regenerated file (a test checks it is current).
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const OUTPUT = join(root, 'packages/ui/src/icon-sprite.generated.ts');

/** Every icon the design system uses, by its Lucide name. Keep sorted. */
export const ICONS = [
  'armchair',
  'arrow-down',
  'arrow-left',
  'arrow-right',
  'arrow-up',
  'beer',
  'book-open',
  'castle',
  'chart-bar',
  'check',
  'chevron-down',
  'chevron-right',
  'clock',
  'crown',
  'dice-5',
  'door-open',
  'download',
  'flame',
  'gamepad-2',
  'hand',
  'hourglass',
  'info',
  'layout-grid',
  'lightbulb',
  'link',
  'list-ordered',
  'lock',
  'log-out',
  'map-pin',
  'message-circle',
  'minus',
  'moon',
  'plus',
  'scroll-text',
  'settings',
  'shuffle',
  'skull',
  'sun',
  'trash-2',
  'triangle-alert',
  'tv',
  'upload',
  'users',
  'volume-2',
  'volume-x',
  'wifi-off',
  'x',
];

const lucideDir = dirname(
  createRequire(join(root, 'packages/ui/package.json')).resolve('lucide-static/package.json'),
);

/**
 * The drawing elements a Lucide icon may hold, each self-closing with plain quoted geometry
 * attributes only (no event handlers, links or styles).
 */
const ELEMENT =
  /<(path|circle|rect|line|polyline|polygon|ellipse)((?:\s+(?:d|cx|cy|r|rx|ry|x|y|x1|x2|y1|y2|width|height|points)="[^"<>]*")*)\s*\/>/g;

/**
 * The inner markup of one Lucide icon, rebuilt from its drawing elements only. Anything else inside
 * the <svg> (a comment, text, another element) stops the build rather than reaching the page.
 */
export function iconBody(name) {
  return drawingOf(readFileSync(join(lucideDir, 'icons', `${name}.svg`), 'utf8'), name);
}

/** `iconBody` for an SVG source given as text. */
export function drawingOf(svg, name) {
  const inner = /<svg[^>]*>([\s\S]*)<\/svg>/.exec(svg)?.[1];
  if (inner === undefined) throw new Error(`lucide-static has no usable ${name}.svg`);
  const elements = [];
  const rest = inner.replace(ELEMENT, (_, tag, attrs) => {
    elements.push(`<${tag}${attrs.replace(/\s+/g, ' ')}/>`);
    return '';
  });
  if (rest.trim() !== '' || elements.length === 0) {
    throw new Error(`lucide-static ${name}.svg holds more than drawing elements`);
  }
  return elements.join('');
}

export function render() {
  const version = JSON.parse(readFileSync(join(lucideDir, 'package.json'), 'utf8')).version;
  const symbols = ICONS.map(
    (name) => `<symbol id="i-${name}" viewBox="0 0 24 24">${iconBody(name)}</symbol>`,
  );
  const licence = readFileSync(join(lucideDir, 'LICENSE'), 'utf8').trim().replaceAll('*/', '* /');
  return [
    `// Generated by scripts/icon-sprite.mjs from lucide-static ${version}. Do not edit.`,
    '',
    `/*! Lucide icons (lucide-static ${version})\n\n${licence}\n*/`,
    '',
    `export const ICON_NAMES = ${JSON.stringify(ICONS)} as const;`,
    '',
    'export type IconName = (typeof ICON_NAMES)[number];',
    '',
    `export const ICON_SPRITE =\n  ${JSON.stringify(symbols.join(''))};`,
    '',
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(OUTPUT, render());
  console.log(`wrote ${OUTPUT} (${ICONS.length} icons)`);
}
